export const colorPatternOptions: SelectOption[] = [
  { value: "homogeneous", label: { pt: "Homogêneo", en: "Homogeneous", es: "Homogéneo", fr: "Homogène" }, desc: { pt: "Toda a camada apresenta uma única cor uniforme, sem manchas, listras ou variações cromáticas discerníveis. Indica condições estáveis de drenagem e pedogênese homogênea ao longo da camada.", en: "The entire layer presents a single uniform color, without spots, streaks, or discernible chromatic variations. Indicates stable drainage conditions and homogeneous pedogenesis throughout the layer.", es: "Toda la capa presenta un único color uniforme, sin manchas, rayas ni variaciones cromáticas discernibles. Indica condiciones estables de drenaje y pedogénesis homogénea a lo largo de la capa.", fr: "Toute la couche présente une seule couleur uniforme, sans taches, raies ou variations chromatiques discernables. Indique des conditions de drainage stables et une pédogenèse homogène dans toute la couche." } },
  { value: "variegated", label: { pt: "Variegado", en: "Variegated", es: "Variegado", fr: "Bigarré" }, desc: { pt: "A camada apresenta duas ou mais cores visíveis, ou manchas de cor diferente sobre uma cor de fundo dominante. Indica alternância de processos de oxidação (manchas avermelhadas) e redução (manchas acinzentadas), associada a flutuações do lençol freático. Registrar a cor dominante e a cor secundária.", en: "The layer presents two or more visible colors, or spots of a different color on a dominant background. Indicates alternating oxidation (reddish spots) and reduction (grayish spots) processes, associated with water table fluctuations. Record both the dominant and secondary colors.", es: "La capa presenta dos o más colores visibles, o manchas de color diferente sobre un color de fondo dominante. Indica alternancia de procesos de oxidación (manchas rojizas) y reducción (manchas grisáceas), asociada a fluctuaciones del nivel freático. Registrar el color dominante y el secundario.", fr: "La couche présente deux couleurs ou plus visibles, ou des taches de couleur différente sur une couleur de fond dominante. Indique une alternance de processus d'oxydation (taches rougeâtres) et de réduction (taches grisâtres), associée à des fluctuations de la nappe. Enregistrer les couleurs dominante et secondaire." } },
];

