/** Fields of ONE soil layer - used both in the schema and in the tests. */
export const soilLayerItemFields: FieldSchema[] = [
  { id: "depth_start",      label: { pt: "Prof. inicial (cm)",  en: "Start depth (cm)",    es: "Prof. inicial (cm)",  fr: "Prof. initiale (cm)" }, type: "text" },
  { id: "depth_end",        label: { pt: "Prof. final (cm)",    en: "End depth (cm)",      es: "Prof. final (cm)",    fr: "Prof. finale (cm)" },   type: "text" },
  { id: "texture",          label: { pt: "Textura",             en: "Texture",             es: "Textura",             fr: "Texture" },             type: "select", options: textureOptions },
  { id: "structure",        label: { pt: "Estrutura",           en: "Structure",           es: "Estructura",          fr: "Structure" },           type: "select", options: structureOptions },
  { id: "color_pattern",    label: { pt: "Padrão de cor",       en: "Color pattern",       es: "Patrón de color",     fr: "Motif de couleur" },    type: "select", options: colorPatternOptions },
  { id: "color_primary",    label: { pt: "Cor primária",        en: "Primary color",       es: "Color primario",      fr: "Couleur primaire" },    type: "select", options: colorTermOptions },
  { id: "color_secondary",  label: { pt: "Cor secundária",      en: "Secondary color",     es: "Color secundario",    fr: "Couleur secondaire" },  type: "select", options: colorTermOptions },
  { id: "cracks",           label: { pt: "Rachaduras",          en: "Cracks",              es: "Grietas",             fr: "Fissures" },            type: "select", options: crackOptions },
  { id: "has_gravel",       label: { pt: "Cascalho",            en: "Gravel",              es: "Grava",               fr: "Graviers" },            type: "boolean", description: { pt: "Presença de fragmentos de rocha com diâmetro superior a 2 mm (cascalhos) ou de pedras na superfície ou interior da camada (pedregosidade). Indica material de origem pedregoso, processo erosivo pretérito que removeu a fração fina, ou herança de material coluvionar.", en: "Presence of rock fragments larger than 2 mm (gravel) or stones on the surface or within the layer. Indicates stony parent material, past erosive processes that removed fine particles, or colluvial material inheritance.", es: "Presencia de fragmentos de roca con diámetro superior a 2 mm (cascajos) o piedras en la superficie o interior de la capa. Indica material de origen pedregoso, procesos erosivos pretéritos que removieron la fracción fina, o herencia de material coluvionar.", fr: "Présence de fragments de roche de diamètre supérieur à 2 mm (graviers) ou de pierres en surface ou dans la couche. Indique un matériau parental pierreux, des processus érosifs passés ayant éliminé la fraction fine, ou un héritage de matériau colluvionnaire." } },
  { id: "has_roots",        label: { pt: "Raízes",              en: "Roots",               es: "Raíces",              fr: "Racines" },             type: "boolean", description: { pt: "Presença de raízes vivas ou mortas na camada analisada. Indica a profundidade efetiva do solo e a atividade biológica do perfil. Raízes em camadas profundas sinalizam boas condições de aeração, ausência de camadas restritivas e solo com profundidade efetiva elevada.", en: "Presence of live or dead roots in the analyzed layer. Indicates the effective soil depth and the biological activity of the profile. Roots in deep layers signal good aeration conditions, absence of restrictive layers, and high effective soil depth.", es: "Presencia de raíces vivas o muertas en la capa analizada. Indica la profundidad efectiva del suelo y la actividad biológica del perfil. Raíces en capas profundas señalan buenas condiciones de aireación, ausencia de capas restrictivas y suelo de elevada profundidad efectiva.", fr: "Présence de racines vivantes ou mortes dans la couche analysée. Indique la profondeur effective du sol et l'activité biologique du profil. Des racines dans les couches profondes signalent de bonnes conditions d'aération, l'absence de couches restrictives et une profondeur effective élevée." } },
  { id: "has_nodules",      label: { pt: "Nódulos",             en: "Nodules",             es: "Nódulos",             fr: "Nodules" },             type: "boolean", description: { pt: "Presença de corpos cimentados de óxido de ferro (goethita, hematita) ou manganês, geralmente de formato arredondado e cor avermelhada a preta. Sinaliza episódios de hidromorfismo passado ou presente, com alternância de condições de oxidação e redução associadas a flutuações do lençol freático.", en: "Presence of cemented bodies of iron oxide (goethite, hematite) or manganese, usually rounded in shape and reddish to black in color. Signals past or present hydromorphism episodes, with alternating oxidizing and reducing conditions associated with water table fluctuations.", es: "Presencia de cuerpos cementados de óxido de hierro (goethita, hematita) o manganeso, generalmente de forma redondeada y color rojizo a negro. Señala episodios de hidromorfismo pasado o presente, con alternancia de condiciones de oxidación y reducción asociadas a fluctuaciones del nivel freático.", fr: "Présence de corps cimentés d'oxyde de fer (goéthite, hématite) ou de manganèse, généralement de forme arrondie et de couleur rougeâtre à noire. Signale des épisodes d'hydromorphie passés ou présents, avec alternance de conditions oxydantes et réductrices associées aux fluctuations de la nappe." } },
  { id: "has_dispersive",   label: { pt: "Dispersivo",          en: "Dispersive",          es: "Dispersivo",          fr: "Dispersif" },           type: "boolean", description: { pt: "Solo com alta concentração de sódio trocável que se dispersa em contato com água pura, formando crosta superficial impermeável e suspensão turva. Indica solo sódico (Solonetz, Planossolo) com alta suscetibilidade à erosão interna por piping e ao encrostamento superficial.", en: "Soil with high exchangeable sodium content that disperses on contact with pure water, forming an impermeable surface crust and a turbid suspension. Indicates sodic soil (Solonetz, Planosol) with high susceptibility to internal erosion by piping and surface crusting.", es: "Suelo con alta concentración de sodio intercambiable que se dispersa en contacto con agua pura, formando costra superficial impermeable y suspensión turbia. Indica suelo sódico (Solonetz, Planossolo) con alta susceptibilidad a la erosión interna por piping y al encostramento superficial.", fr: "Sol à haute teneur en sodium échangeable qui se disperse au contact de l'eau pure, formant une croûte de surface imperméable et une suspension trouble. Indique un sol sodique (Solonetz, Planosol) à haute susceptibilité à l'érosion interne par piping et à la formation de croûtes de surface." } },
  { id: "has_hardened",     label: { pt: "Endurecido",          en: "Hardened",            es: "Endurecido",          fr: "Durci" },               type: "boolean", description: { pt: "Horizonte com consistência muito dura a extremamente dura quando seco, resistente à penetração de raízes e à escavação manual. Pode indicar horizonte coeso (comum no Nordeste brasileiro), fragipã ou horizonte plíntico, restringindo a infiltração de água e o crescimento radicular.", en: "Horizon with very hard to extremely hard consistency when dry, resistant to root penetration and manual excavation. May indicate a cohesive horizon (common in northeastern Brazil), fragipan, or plinthic horizon, restricting water infiltration and root growth.", es: "Horizonte con consistencia muy dura a extremadamente dura cuando seco, resistente a la penetración de raíces y a la excavación manual. Puede indicar horizonte cohesivo (común en el Nordeste brasileño), fragipán u horizonte plíntico, restringiendo la infiltración de agua y el crecimiento radicular.", fr: "Horizon à consistance très dure à extrêmement dure quand sec, résistant à la pénétration des racines et à l'excavation manuelle. Peut indiquer un horizon cohésif (commun dans le Nordeste brésilien), un fragipan ou un horizon plinthique, restreignant l'infiltration de l'eau et la croissance racinaire." } },
  { id: "has_water_table",  label: { pt: "Lençol freático",     en: "Water table",         es: "Nivel freático",      fr: "Nappe phréatique" },    type: "boolean", description: { pt: "Afloramento de água durante a descrição da camada, indicando que o lençol freático está dentro do perfil no momento do levantamento. Evidencia drenagem imperfeita a muito mal drenada, com implicações diretas para a vegetação que pode ser sustentada no sítio e para os processos geossistêmicos locais.", en: "Water seeping into the layer during description, indicating the water table is within the profile at the time of the survey. Evidences imperfect to very poorly drained conditions, with direct implications for the vegetation that can be sustained at the site and for local geosystemic processes.", es: "Afloramiento de agua durante la descripción de la capa, indicando que el nivel freático está dentro del perfil en el momento del levantamiento. Evidencia drenaje imperfecto a muy mal drenado, con implicaciones directas para la vegetación que puede sustentarse en el sitio y para los procesos geosistémicos locales.", fr: "Affleurement d'eau pendant la description de la couche, indiquant que la nappe phréatique est dans le profil au moment du levé. Témoigne d'un drainage imparfait à très mauvais, avec des implications directes pour la végétation pouvant être soutenue sur le site et pour les processus géosystémiques locaux." } },
];

